import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  checkboxGroupCaptionClassName,
  checkboxGroupControlClassName,
  checkboxGroupIndicatorClassName,
  checkboxGroupItemClassName,
  checkboxGroupItemsClassName,
  checkboxGroupRootClassName,
} from "./view";

export {
  checkboxGroupCaptionClassName,
  checkboxGroupControlClassName,
  checkboxGroupIndicatorClassName,
  checkboxGroupItemClassName,
  checkboxGroupItemsClassName,
  checkboxGroupRootClassName,
} from "./view";

export type CheckboxGroupStyle = Readonly<Record<string, string>>;

export type ParentState = "checked" | "indeterminate" | "unchecked";

export type GroupViewConfig = Readonly<{
  label: string;
  labelId: string;
  children: readonly Html[];
  name?: string | undefined;
  disabled?: boolean | undefined;
  required?: boolean | undefined;
  className?: string | undefined;
  style?: CheckboxGroupStyle | undefined;
}>;

export type ItemViewConfig<ParentMessage> = Readonly<{
  value: string;
  selectedValues: readonly string[];
  onValueChange: ParentMessage;
  label: string;
  disabled?: boolean | undefined;
  required?: boolean | undefined;
  className?: string | undefined;
  style?: CheckboxGroupStyle | undefined;
}>;

export type ParentItemViewConfig<ParentMessage> = Readonly<{
  selectedValues: readonly string[];
  allValues: readonly string[];
  onValueChange: ParentMessage;
  label: string;
  disabled?: boolean | undefined;
  className?: string | undefined;
  style?: CheckboxGroupStyle | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const includesValue = <Value extends string>(
  selectedValues: readonly Value[],
  value: Value
): boolean => selectedValues.includes(value);

export const toggleValue = <Value extends string>(
  selectedValues: readonly Value[],
  value: Value
): readonly Value[] =>
  includesValue(selectedValues, value)
    ? selectedValues.filter((selectedValue) => selectedValue !== value)
    : [...selectedValues, value];

export const parentState = (
  selectedValues: readonly string[],
  allValues: readonly string[]
): ParentState => {
  const selectedCount = allValues.filter((value) =>
    selectedValues.includes(value)
  ).length;

  if (selectedCount === 0) {
    return "unchecked";
  }

  if (selectedCount === allValues.length) {
    return "checked";
  }

  return "indeterminate";
};

const stateAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  checked: boolean,
  indeterminate: boolean,
  disabled: boolean,
  required: boolean
) => [
  ...(checked
    ? [h.DataAttribute("checked", "")]
    : [h.DataAttribute("unchecked", "")]),
  ...(indeterminate ? [h.DataAttribute("indeterminate", "")] : []),
  ...(disabled ? [h.DataAttribute("disabled", "")] : []),
  ...(required ? [h.DataAttribute("required", "")] : []),
];

const itemMarkup = <ParentMessage>({
  label,
  checked,
  indeterminate,
  onValueChange,
  disabled,
  required,
  className,
  style,
}: Readonly<{
  label: string;
  checked: boolean;
  indeterminate: boolean;
  onValueChange: ParentMessage;
  disabled: boolean;
  required: boolean;
  className?: string | undefined;
  style?: CheckboxGroupStyle | undefined;
}>): Html => {
  const h = html<ParentMessage>();
  const state = stateAttributes(h, checked, indeterminate, disabled, required);

  return h.label(
    [
      ...state,
      ...(disabled ? [] : [h.OnClick(onValueChange)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(checkboxGroupItemClassName, className)),
    ],
    [
      h.span(
        [
          h.Attribute("role", "checkbox"),
          h.AriaLabel(label),
          h.Attribute(
            "aria-checked",
            indeterminate ? "mixed" : checked ? "true" : "false"
          ),
          ...(disabled ? [h.Attribute("aria-disabled", "true")] : []),
          ...(required ? [h.Attribute("aria-required", "true")] : []),
          ...state,
          h.Class(checkboxGroupControlClassName),
        ],
        [
          h.span(
            [...state, h.Class(checkboxGroupIndicatorClassName)],
            [indeterminate ? "—" : checked ? "✓" : ""]
          ),
        ]
      ),
      h.span([], [label]),
    ]
  );
};

export const groupView = <ParentMessage>({
  label,
  labelId,
  children,
  name,
  disabled = false,
  required = false,
  className,
  style,
}: GroupViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "group"),
      h.Attribute("aria-labelledby", labelId),
      ...(name === undefined ? [] : [h.DataAttribute("name", name)]),
      ...(disabled ? [h.DataAttribute("disabled", "")] : []),
      ...(required ? [h.Attribute("aria-required", "true")] : []),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(checkboxGroupRootClassName, className)),
    ],
    [
      h.div([h.Id(labelId), h.Class(checkboxGroupCaptionClassName)], [label]),
      h.div([h.Class(checkboxGroupItemsClassName)], children),
    ]
  );
};

export const itemView = <ParentMessage>({
  value,
  selectedValues,
  onValueChange,
  label,
  disabled = false,
  required = false,
  className,
  style,
}: ItemViewConfig<ParentMessage>): Html =>
  itemMarkup({
    label,
    checked: includesValue(selectedValues, value),
    indeterminate: false,
    onValueChange,
    disabled,
    required,
    className,
    style,
  });

export const parentItemView = <ParentMessage>({
  selectedValues,
  allValues,
  onValueChange,
  label,
  disabled = false,
  className,
  style,
}: ParentItemViewConfig<ParentMessage>): Html => {
  const state = parentState(selectedValues, allValues);

  return itemMarkup({
    label,
    checked: state === "checked",
    indeterminate: state === "indeterminate",
    onValueChange,
    disabled,
    required: false,
    className,
    style,
  });
};

export const checkboxGroupRootClassName = "space-y-2";

export const checkboxGroupCaptionClassName =
  "text-sm font-medium text-gray-950";

export const checkboxGroupItemsClassName = "space-y-2";

export const checkboxGroupItemClassName =
  "flex cursor-pointer items-center gap-2 text-sm text-gray-700 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const checkboxGroupControlClassName =
  "inline-flex h-5 w-5 shrink-0 items-center justify-center rounded border border-gray-300 bg-white text-xs font-semibold text-white transition-colors data-[checked]:border-accent-600 data-[checked]:bg-accent-600 data-[indeterminate]:border-accent-600 data-[indeterminate]:bg-accent-600 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600";

export const checkboxGroupIndicatorClassName =
  "leading-none opacity-0 data-[checked]:opacity-100 data-[indeterminate]:opacity-100";

import { Match as M, Schema as S } from "effect";
import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, expect, test } from "vitest";

import * as CheckboxGroup from "./index";

const ToggledValue = m("ToggledValue", { value: S.String });
const ToggledAll = m("ToggledAll");
const Message = S.Union([ToggledValue, ToggledAll]);
type Message = typeof Message.Type;

type Model = Readonly<{
  selectedValues: readonly string[];
}>;

const allValues = ["fuji-apple", "gala-apple", "granny-smith-apple"];

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly []] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly []]>(),
    M.tagsExhaustive({
      ToggledValue: ({ value }) => [
        evo(model, {
          selectedValues: (selectedValues) =>
            CheckboxGroup.toggleValue(selectedValues, value),
        }),
        [],
      ],
      ToggledAll: () => [
        evo(model, {
          selectedValues: (selectedValues) =>
            CheckboxGroup.parentState(selectedValues, allValues) === "checked"
              ? []
              : allValues,
        }),
        [],
      ],
    })
  );

const view = (model: Model): Html =>
  CheckboxGroup.groupView<Message>({
    label: "Apples",
    labelId: "apples-label",
    children: [
      CheckboxGroup.parentItemView<Message>({
        selectedValues: model.selectedValues,
        allValues,
        label: "All apples",
        onValueChange: ToggledAll(),
      }),
      CheckboxGroup.itemView<Message>({
        value: "fuji-apple",
        selectedValues: model.selectedValues,
        label: "Fuji",
        onValueChange: ToggledValue({ value: "fuji-apple" }),
      }),
      CheckboxGroup.itemView<Message>({
        value: "gala-apple",
        selectedValues: model.selectedValues,
        label: "Gala",
        onValueChange: ToggledValue({ value: "gala-apple" }),
      }),
      CheckboxGroup.itemView<Message>({
        value: "granny-smith-apple",
        selectedValues: model.selectedValues,
        label: "Granny Smith",
        onValueChange: ToggledValue({ value: "granny-smith-apple" }),
      }),
    ],
  });

describe("Base UI Checkbox Group registry view", () => {
  test("renders Base UI group anatomy and toggles values", () => {
    Scene.scene(
      { update, view },
      Scene.with({ selectedValues: ["fuji-apple"] }),
      Scene.expect(Scene.role("group", { name: "Apples" })).toExist(),
      Scene.expect(Scene.role("checkbox", { name: "Fuji" })).toHaveAttr(
        "aria-checked",
        "true"
      ),
      Scene.expect(Scene.role("checkbox", { name: "Gala" })).toHaveAttr(
        "aria-checked",
        "false"
      ),
      Scene.expect(Scene.role("checkbox", { name: "All apples" })).toHaveAttr(
        "aria-checked",
        "mixed"
      ),
      Scene.click(Scene.text("Gala")),
      Scene.expect(Scene.role("checkbox", { name: "Gala" })).toHaveAttr(
        "aria-checked",
        "true"
      ),
      Scene.expect(Scene.role("checkbox", { name: "All apples" })).toHaveAttr(
        "aria-checked",
        "mixed"
      ),
      Scene.click(Scene.text("All apples")),
      Scene.expect(Scene.role("checkbox", { name: "Granny Smith" })).toHaveAttr(
        "aria-checked",
        "true"
      ),
      Scene.expect(Scene.role("checkbox", { name: "All apples" })).toHaveAttr(
        "aria-checked",
        "true"
      )
    );
  });

  test("computes next array values and parent state", () => {
    expect(CheckboxGroup.toggleValue(["fuji-apple"], "gala-apple")).toEqual([
      "fuji-apple",
      "gala-apple",
    ]);
    expect(
      CheckboxGroup.toggleValue(["fuji-apple", "gala-apple"], "fuji-apple")
    ).toEqual(["gala-apple"]);
    expect(CheckboxGroup.parentState([], allValues)).toBe("unchecked");
    expect(CheckboxGroup.parentState(["fuji-apple"], allValues)).toBe(
      "indeterminate"
    );
    expect(CheckboxGroup.parentState(allValues, allValues)).toBe("checked");
  });
});
